// ─────────────────────────────────────────────────────────────────────────
// Assets statiques du site (logo, favicon) encodés en base64.
//
// Pourquoi ce fichier plutôt qu'un import binaire ou un objet R2 ?
// Le Worker n'a accès qu'à des imports texte (cf. index.html/admin.html
// importés tels quels) et l'upload vers R2 nécessite un accès au bucket en
// prod. On garde donc ces petits assets fixes ici, servis par des routes
// dédiées dans worker.js (GET /logo.jpg, /favicon.ico, /apple-touch-icon.png,
// /icon.png) avec un cache navigateur long (immutable) — voir serveStaticAsset().
//
// - LOGO_JPG_BASE64 : le logo du club (109×120), auparavant dupliqué tel
//   quel dans index.html (nav + footer), ~7.5 Ko de base64 à chaque endroit.
//   Il est désormais servi une seule fois via /logo.jpg et mis en cache par
//   le navigateur, au lieu d'être retéléchargé à chaque chargement de page.
// - FAVICON_ICO_BASE64, APPLE_TOUCH_ICON_BASE64, ICON_512_BASE64 : favicon
//   généré à partir du logo officiel du club (source haute résolution
//   auparavant committée sous src/Logo 1 nnoir copie(1).jpg — 2,6 Mo, jamais
//   utilisée par le code — remplacée par ces exports web déjà optimisés).
//   Le site n'avait jusqu'ici aucun favicon (icône générique dans l'onglet).
// ─────────────────────────────────────────────────────────────────────────

export const LOGO_JPG_BASE64 =
  '';

export const FAVICON_ICO_BASE64 =
  '';

export const APPLE_TOUCH_ICON_BASE64 =
  '';

export const ICON_512_BASE64 =
  '';

